import 'package:flutter/widgets.dart';

import 'music_catalog.g.dart';
import 'sound_catalog.dart';

export 'music_catalog.g.dart' show kMusicCatalog, kMusicCategories;

/// One background-music loop. The catalog (54 tracks) is generated by
/// `tool/generate_music.py` into `music_catalog.g.dart`.
@immutable
class MusicTrack implements SoundItem {
  @override
  final String name;
  @override
  final String label;
  @override
  final String category;
  @override
  final IconData icon;
  @override
  final String fileName;
  @override
  final String? pack;

  const MusicTrack(
      this.name, this.label, this.category, this.icon, this.fileName,
      {this.pack});

  /// Flutter asset path — only valid for bundled tracks (`pack == null`).
  String get asset => 'assets/sounds/$fileName';

  SoundCategory get categoryInfo =>
      kMusicCategories.firstWhere((c) => c.id == category);

  // Tracks referenced directly from code (defaults, migration, tests).
  static const MusicTrack twilightPad = musicTwilightPad;
  static const MusicTrack musicBox = musicMusicBox;
  static const MusicTrack feltPiano = musicFeltPiano;
  static const MusicTrack warmKeys = musicWarmKeys;

  static List<MusicTrack> get values => kMusicCatalog;

  static MusicTrack? byName(String? name) {
    for (final t in kMusicCatalog) {
      if (t.name == name) return t;
    }
    return null;
  }

  @override
  bool operator ==(Object other) => other is MusicTrack && other.name == name;

  @override
  int get hashCode => name.hashCode;

  @override
  String toString() => 'MusicTrack($name)';
}
